import {occasionTreatments,occasionDirection,occasionTreatmentName} from './gift-identity.js';
import {bookTexturePaths,resolveBookFinish} from './book-finish.js';
import {occasions} from './occasions.js';
import {cleanAppearance,appearancePalette,giftArtworkSource} from './appearance.js';
import {cleanStationery,stationeryLayouts,paintStationery,ensureStationeryFonts} from './stationery.js';
import {cleanStoryDesign,storyLayouts,drawStoryFrame} from './story-design.js';
import {cleanExperience} from './experience.js';
export const occasionFamilies={amizade:'familia',aniversario:'aniversario',aniversario_namoro:'amor',mesversario:'aniversario',casamento:'casamento',bodas:'casamento',namorados:'amor',maes:'familia',pais:'familia',avos:'familia',natal:'natal',anonovo:'conquistas',pascoa:'pascoa',formatura:'conquistas',pedido_namoro:'amor',desculpas:'amor',pet:'pet',outro:'familia'};
const directions={natal:['coral','noite','perola'],aniversario:['mel','azul','coral'],casamento:['perola','cacau','azul'],familia:['cacau','amora','ceu'],amor:['amora','perola','noite'],pascoa:['terracota','mel','ceu'],conquistas:['perola','azul','noite'],pet:['cacau','mel','terracota']};
const headlines={amizade:'Tem um pouco de nós aqui.',aniversario:'Mais um capítulo bonito.',aniversario_namoro:'Ainda bem que é com você.',mesversario:'Pequenos dias. Grandes histórias.',casamento:'O começo do nosso sim.',bodas:'O nosso sim continua.',namorados:'Meu lugar favorito é com você.',maes:'Seu carinho é casa.',pais:'Pai, a nossa história fica.',avos:'Carinho que atravessa gerações.',natal:'O melhor presente é estar perto.',anonovo:'Que venham os próximos capítulos.',pascoa:'Carinho para compartilhar.',formatura:'O futuro começa aqui.',pedido_namoro:'Vamos escrever nossa história?',desculpas:'Uma nova página para nós.',pet:'Minha companhia favorita.',outro:'Um pequeno gesto. Todo o carinho.'};
export function coverOptions(occasion='amizade',format='livro'){
 if(!occasions[occasion])occasion='amizade';if(!['stories','livro','cartao','convite'].includes(format))format='livro';
 const art=occasionDirection(occasion),family=occasionFamilies[occasion],layouts=Object.entries(format==='stories'?storyLayouts:stationeryLayouts);
 return layouts.flatMap(([layout,label],i)=>directions[family].map((palette,j)=>{const background=[art.background,'cotton','frame','linen','plain'][i%5],appearance=cleanAppearance({palette,background,scene:['paper','sky','cocoa'][j],animation:['gentle','classic','confetti','float','pop','spin'][i%6],custom:true,paper:j===2?art.ink:j===1?art.soft:art.paper,ink:j===2?art.paper:art.ink,accent:j===2?art.soft:art.accent,intensity:.2,themeStyle:(i*3+j)%20,themeEffect:j===2?'sparkle':'none',coverSurface:j===1?'paper':'cloth'}),storyLayout=Object.keys(storyLayouts)[i];return {id:occasion+'-'+format+'-'+String(i*3+j+1).padStart(2,'0'),number:i*3+j+1,occasion,format,family,bookFinish:resolveBookFinish({bookFinish:{material:j===1?'paper':art.material}}),name:occasionTreatmentName(occasion,(i*3+j)%20)+' · '+label,layout,appearance,openingStyle:family,stationeryDesign:cleanStationery({layout,title:headlines[occasion],seal:true}),storyDesign:cleanStoryDesign({layout:storyLayout,palette,background,custom:true,paper:appearance.paper,ink:appearance.ink,accent:appearance.accent,title:headlines[occasion],font:j===2?'clean':'editorial',transition:['fade','slide','zoom'][j],decoration:'capy'})};}));
}
export function coverExample(cover){const family=cover.family,photo='assets/photo-'+({familia:'mother',conquistas:'friends',aniversario:'friends',pet:'family',natal:'family',pascoa:'family'}[family]||'couple')+'.webp',second='assets/photo-grandmother.webp';return {...cover,coverId:cover.id,coverArt:family,isExample:true,draftId:'catalog-example',character:'capy',person:0,texture:'algodao',pattern:'signature-0',theme:occasions[cover.occasion],recipient:cover.format==='convite'||['casamento','bodas'].includes(cover.occasion)?'Lia & Rafa':({maes:'Mãe',pais:'Pai',avos:'Vó Lúcia',pet:'Nosso melhor amigo'})[cover.occasion]||'Lia',message:'As melhores lembranças são feitas de pequenos momentos juntos. Que bom ter você na minha história.',color:appearancePalette(cover.appearance).accent,photo,photos:[{src:photo,caption:'A gente, do nosso jeito.'},{src:second,caption:'Carinho que fica.'}],pages:[{title:'O começo de tudo',message:'Cada lembrança merece seu lugar.',photo},{title:'O que vem pela frente',message:'Ainda temos muitas histórias para viver.',photo:second}],eventDate:'2026-12-20',eventPlace:'Casa do Jardim',experience:cleanExperience({sender:'Rafa',reply:false})};}
const imageCache=new Map();async function image(src){if(!imageCache.has(src))imageCache.set(src,new Promise(resolve=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>resolve(null);i.src=src;}));return imageCache.get(src);}
export function initCoverCatalog({getState,isEditing,onApply,onPreview,onCreate}){
 const dialog=document.createElement('dialog');dialog.className='cover-catalog-dialog';dialog.setAttribute('aria-labelledby','cover-catalog-title');dialog.innerHTML='<header><div><p class="catalog-eyebrow">Coleções Capimimo</p><h2 id="cover-catalog-title">Uma capa que tem a ver.</h2></div><button type="button" class="catalog-close" aria-label="Fechar coleção">×</button></header><p>30 opções em cada ocasião e formato. 20 tratamentos próprios de cada ocasião, dez composições e paletas coordenadas. Depois, cada detalhe pode ficar com a sua cara.</p><div class="catalog-filters"><label>Ocasião<select class="catalog-occasion"></select></label><label>Formato<select class="catalog-format"><option value="livro">Livro com páginas</option><option value="cartao">Cartão simples</option><option value="convite">Convite 3D</option><option value="stories">Stories</option></select></label></div><label class="catalog-preserve"><input type="checkbox" checked> Manter meus textos ao trocar de capa</label><div class="catalog-grid"></div><nav class="catalog-pagination" aria-label="Páginas da coleção"><button class="catalog-prev">← Anteriores</button><output aria-live="polite"></output><button class="catalog-next">Próximas →</button></nav>';document.body.append(dialog);
 const picker=dialog.querySelector('.catalog-occasion');for(const [key,value] of Object.entries(occasions))picker.add(new Option(value.label,key));let page=0,version=0;
 async function render(){const own=++version,occasion=picker.value,format=dialog.querySelector('.catalog-format').value,options=coverOptions(occasion,format);dialog.querySelector('.catalog-preserve').hidden=!isEditing();dialog.querySelector('.catalog-prev').disabled=page===0;dialog.querySelector('.catalog-next').disabled=page===4;dialog.querySelector('output').textContent=(page*6+1)+'–'+(page*6+6)+' de 30';const grid=dialog.querySelector('.catalog-grid');grid.replaceChildren();await ensureStationeryFonts();if(own!==version)return;
  for(const cover of options.slice(page*6,page*6+6)){const article=document.createElement('article'),canvas=document.createElement('canvas');canvas.width=cover.format==='cartao'?420:300;canvas.height=cover.format==='cartao'?300:400;canvas.setAttribute('aria-label',cover.name);const title=document.createElement('h3');title.textContent=String(cover.number).padStart(2,'0')+' · '+cover.name;const preview=document.createElement('button');preview.textContent=cover.format==='stories'?'Assistir exemplo':'Experimentar em 3D';preview.addEventListener('click',()=>{dialog.close();onPreview(coverExample(cover));});const use=document.createElement('button');use.className='catalog-use';use.textContent=isEditing()?'Usar esta capa':'Criar minha versão';use.addEventListener('click',()=>{if(isEditing()){const preserve=dialog.querySelector('.catalog-preserve input').checked;onApply(cover,preserve);dialog.close();}else{dialog.close();onCreate(cover);}});article.append(canvas,title,preview,use);grid.append(article);const data=coverExample(cover);if(format==='stories'){canvas.width=270;canvas.height=480;drawStoryFrame(canvas,data,{kind:'cover'}).catch(()=>{});}else Promise.all([image(data.photo),image(giftArtworkSource(data)),image('assets/'+data.theme.sheet+'.webp'),image(data.photos[1].src),format==='livro'?image(bookTexturePaths(data.bookFinish)[0]):null]).then(([photo,pattern,sprite,other,material])=>{if(own===version)paintStationery(canvas,data,{photo,photos:[other],pattern,sprite,material});});}
 }
 function open(occasion,format){const state=getState();picker.value=occasions[occasion]?occasion:state.occasion;dialog.querySelector('.catalog-format').value=format||state.format;page=0;dialog.showModal();render();}
 dialog.querySelector('.catalog-close').addEventListener('click',()=>dialog.close());dialog.querySelector('.catalog-prev').addEventListener('click',()=>{page=Math.max(0,page-1);render();});dialog.querySelector('.catalog-next').addEventListener('click',()=>{page=Math.min(4,page+1);render();});dialog.querySelectorAll('select').forEach(select=>select.addEventListener('change',()=>{page=0;render();}));return {open};
}
